<script lang="ts">
  import { onMount } from 'svelte'
  import { api } from '$lib/api'
  let rows: any[] = []; let error = ''; let pageNumber = 1; let pages = 1; let total = 0; let loading = false
  async function load() { loading = true; error = ''; try { const result = await api<{ data: any[]; pagination: { pages: number; total: number } }>(`/admin/audit-logs?page=${pageNumber}&limit=50`); rows = result.data; pages = Math.max(1, result.pagination.pages); total = result.pagination.total } catch (reason: any) { error = reason.message } finally { loading = false } }
  onMount(() => { void load() })
</script>
<main class="admin-content"><div class="page-title"><div><span class="kicker">ACCOUNTABILITY</span><h1>Audit log</h1><p>Administrator actions across users, forms, reports, and settings.</p></div><span class="count-pill">{total} total</span></div>{#if error}<div class="notice error">{error}</div>{/if}<section class="panel table-panel"><table><thead><tr><th>Action</th><th>Actor</th><th>Target</th><th>Time</th></tr></thead><tbody>{#each rows as row}<tr><td><b>{row.action}</b></td><td>{row.actor?.name || 'Administrator'}<small>{row.actor?.email || ''}</small></td><td>{row.targetType} {row.targetId && `· ${row.targetId}`}</td><td>{new Date(row.createdAt).toLocaleString()}</td></tr>{/each}</tbody></table>{#if !rows.length}<p class="table-empty">{loading ? 'Loading audit log…' : 'No administrator actions have been recorded yet.'}</p>{/if}</section><div class="admin-pagination"><span>Page {pageNumber} of {pages}</span><div><button class="secondary-button" disabled={pageNumber <= 1 || loading} onclick={() => { pageNumber -= 1; void load() }}>Previous</button><button class="secondary-button" disabled={pageNumber >= pages || loading} onclick={() => { pageNumber += 1; void load() }}>Next</button></div></div></main>
